const mobileHamburger = document.getElementById("mobile-hamburger");
    const mobileMenu = document.getElementById("mobile-menu");
    const mobileHamburgerIcon = document.getElementById("mobile-hamburger-icon");

    mobileHamburger.addEventListener("click", () => {
      const isOpen = mobileMenu.style.display === "flex";

      if (isOpen) {
        mobileMenu.style.display = "none";
        mobileHamburgerIcon.classList.replace("bi-x", "bi-list");
      } else {
        mobileMenu.style.display = "flex";
        mobileHamburgerIcon.classList.replace("bi-list", "bi-x");
      }
    });

    // Accordion toggle when clicking entire <a>
    document.querySelectorAll(".mobile-has-submenu > a").forEach(link => {
      link.addEventListener("click", (e) => {
        e.preventDefault(); // stop navigation
        const parentLi = link.parentElement;

        // Accordion effect: close siblings
        parentLi.parentElement.querySelectorAll(":scope > li.mobile-open").forEach(openLi => {
          if (openLi !== parentLi) {
            openLi.classList.remove("mobile-open");
          }
        });

        parentLi.classList.toggle("mobile-open");
      });
    });
